const ICONS={menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',home:'<path d="m3 10 9-7 9 7v10H3V10Z"/><path d="M9 20v-6h6v6"/>',crown:'<path d="m2 8 5 4 5-7 5 7 5-4-2 11H4L2 8Z"/><path d="M4 22h16"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M17 5a3 3 0 0 1 0 6M17 15a6 6 0 0 1 4 6"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21a8 8 0 0 1 16 0"/>',plus:'<path d="M12 5v14M5 12h14"/>',shield:'<path d="M12 2 3 6v6c0 5 3.3 8 9 10 5.7-2 9-5 9-10V6l-9-4Z"/><path d="m8 12 3 3 5-6"/>',globe:'<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3a16 16 0 0 1 0 18M12 3a16 16 0 0 0 0 18"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',back:'<path d="m15 18-6-6 6-6"/>',chevron:'<path d="m9 6 6 6-6 6"/>',database:'<ellipse cx="12" cy="5" rx="9" ry="3"/><path d="M3 5v14c0 4 18 4 18 0V5M3 12c0 4 18 4 18 0"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l4 2"/>',wallet:'<rect x="3" y="5" width="18" height="15" rx="2"/><path d="M17 11h5v5h-5a2.5 2.5 0 0 1 0-5Z"/>',list:'<path d="M9 6h13M9 12h13M9 18h13M3 6h1M3 12h1M3 18h1"/>',edit:'<path d="m3 17 1 4 4-1L20 8a3 3 0 0 0-4-4L3 17Z"/>',search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',lock:'<rect x="4" y="11" width="16" height="11" rx="2"/><path d="M8 11V7a4 4 0 0 1 8 0v4"/>',check:'<path d="m4 12 5 5L20 6"/>',alert:'<path d="M12 3 2 21h20L12 3Z"/><path d="M12 9v5M12 18h.01"/>',mail:'<rect x="2" y="5" width="20" height="14" rx="2"/><path d="m2 7 10 7 10-7"/>',settings:'<path d="M4 5h16M4 12h16M4 19h16"/><circle cx="8" cy="5" r="2"/><circle cx="16" cy="12" r="2"/><circle cx="10" cy="19" r="2"/>',history:'<path d="M3 12a9 9 0 1 1 3 6.7M3 18v-5h5M12 7v5l4 2"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 2v6M17 2v6M3 10h18"/>',book:'<path d="M4 4h12a3 3 0 0 1 3 3v14H7a3 3 0 0 1-3-3V4ZM7 21a3 3 0 0 1 0-6h12"/>',spark:'<path d="m12 2 2.3 7.7L22 12l-7.7 2.3L12 22l-2.3-7.7L2 12l7.7-2.3L12 2Z"/>',external:'<path d="M12 3h9v9M21 3l-11 11M19 14v7H3V5h7"/>',logout:'<path d="M10 3H4v18h6M15 7l5 5-5 5M8 12h12"/>'};
function I(name,large=false){return `<svg aria-hidden="true" class="icon${large?' lg':''}" viewBox="0 0 24 24">${ICONS[name]||ICONS.shield}</svg>`}
function esc(x){return String(x??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#39;')}
function date(){return new Date().toISOString().slice(0,10)}
function time(){return new Date().toLocaleString('es-ES',{dateStyle:'short',timeStyle:'short'})}
const DEMO_KEY='dea-v6-demo-only';
function seed(){return {agents:[{id:1,habbo:'AgenteEjemplo',discord:'Cuenta de prueba',rank:3,date:'2026-10-10',last:'2026-10-10'},{id:2,habbo:'InstructorDemo',discord:'Cuenta de prueba',rank:7,date:'2026-10-09',last:'2026-10-11'}],requests:[{id:1,habbo:'NuevoEjemplo',discord:'Discord de prueba',state:'pendiente',date:'2026-10-15'}],promotions:[],payments:[],extra:[],audit:[],rules:Object.fromEntries(GROUPS.map(g=>[g.id,{period:g.period,pay:g.pay,hours:g.hours}])),seq:3}}
let demo=null;try{demo=JSON.parse(sessionStorage.getItem(DEMO_KEY))}catch{} if(!demo)demo=seed();
const demoMode=false;let connected=false,identity=null,sidebarOpen=true,mobileOpen=false,filter='',selectedAgent='',joinNick='',lastError='';
const pathname=()=>decodeURI(location.hash.replace(/^#\/?/,'').split('?')[0]||'').replace(/^\//,'')||'inicio';
const route=(name)=>{location.hash='/'+name};
function ruleFor(cat){if(!demoMode&&realData.policies?.length){const p=realData.policies.find(x=>x.category===cat);if(p)return {period:p.period_label,hours:p.payroll_hours,pay:p.payroll_credits}}return demo.rules[cat]}
function save(){try{sessionStorage.setItem(DEMO_KEY,JSON.stringify(demo))}catch{ /* Entornos sin almacenamiento: demo en memoria */ }}
function log(action,detail){demo.audit.unshift({id:Date.now()+Math.random(),by:'FOUNDER DEMO',action,detail,when:time()});save()}
function show(msg){let old=document.querySelector('.toast');if(old)old.remove();let e=document.createElement('div');e.className='toast';e.setAttribute('role','status');e.textContent=msg;document.body.append(e);setTimeout(()=>e.remove(),4000)}
async function api(path,method='GET',payload){let opt={method,credentials:'same-origin',headers:{Accept:'application/json'}};if(payload!==undefined){opt.headers['Content-Type']='application/json';opt.body=JSON.stringify(payload)}const r=await fetch(path,opt);const d=await r.json();if(!r.ok)throw Error(d.error||'Operación no disponible');return d}
async function checkSession(){try{const h=await fetch('/api/health',{cache:'no-store'});if(!h.ok)return;const d=await h.json();connected=!!d.configured;if(connected){let s=await api('/api/session');identity=s.user||null}}catch{connected=false}finally{render();if(identity?.founder&&!demoMode)fetchReal()}}
function role(){return identity?.founder?'founder':identity?'user':'visitor'}
function isVip(){return !!identity?.founder}
function layoutHome(){return `<div class="shell-home"><div class="home-glow"></div><header class="home-bar"><a class="home-brand" href="#/inicio" aria-label="DEA HABBO ES, volver al inicio"><img src="./logo-dea-es.png" alt="Logo oficial DEA ES"><span>DEA HABBO ES</span></a><span class="micro">HABBO HOTEL · AGENCIA</span></header><main class="landing"><div class="hero-eagle"><img src="./aguila-dea-original.jpg" alt="Águila dorada y azul del Departamento Especial de Agentes"></div><div class="hero-kicker">DEPARTAMENTO ESPECIAL DE AGENTES</div><h1 class="gradient-ink">DEA HABBO ES</h1><p class="hero-caption">Disciplina · Honor · Lealtad<br>Tu espacio de información, acceso y gestión de la agencia en Habbo Hotel.</p><span class="pill">${I('spark')} PLATAFORMA OFICIAL DE LA AGENCIA</span><div class="choice-grid"><a href="#/vip" class="choice vip">${I('crown',true)}<strong>ACCESO VIP</strong><small>Centro de Control exclusivo para la dirección, Founders y personal autorizado.</small><span class="choice-arrow">${I('arrow')}</span></a><a href="#/unete" class="choice join">${I('user',true)}<strong>ÚNETE A DEA</strong><small>Completa tu formación en Habbo y solicita tu expediente oficial mediante Discord.</small><span class="choice-arrow">${I('arrow')}</span></a><a href="#/publico" class="choice public">${I('globe',true)}<strong>WEB PÚBLICA</strong><small>Conoce la agencia, su jerarquía, departamentos y equipo fundador.</small><span class="choice-arrow">${I('arrow')}</span></a></div><p class="home-desc">En Habbo Hotel, los primeros 45 minutos de formación se gestionan en la sala. El registro web comienza en R2 · Agente de Enlace.</p></main><footer class="home-foot">© DEA HABBO ES · Habbo Hotel es una marca de sus propietarios. Comunidad de fans independiente. <br> Designed by <strong>10PEDRO</strong> — <a href="https://yourdesigngpt.netlify.app/" target="_blank" rel="noopener noreferrer">YourDesignGPT ${I('external')}</a></footer></div>`}
const NAV_PUBLIC=[['publico','Inicio público','home'],['publico/agencia','La agencia','shield'],['publico/jerarquia','Jerarquía','list'],['publico/departamentos','Departamentos','users'],['publico/founders','Founders','crown'],['publico/ingreso','Cómo ingresar','user'],['publico/normativa','Normativa','book']];
const NAV_VIP=[['vip','Resumen','home'],['vip/solicitudes','Solicitudes','user'],['vip/agentes','Agentes','users'],['vip/ascensos','Ascensos','arrow'],['vip/rangos','Rangos y normas','list'],['vip/nominas','Nóminas y extras','wallet'],['vip/historial','Historial','history'],['vip/configuracion','Configuración','settings']];
const NAV_AGENT=[['ficha','Mi expediente','user'],['ficha/historial','Mis ascensos','history'],['ficha/pagos','Mis pagos','wallet']];
function area(p){return p.startsWith('publico')?'publico':p.startsWith('vip')?'vip':p.startsWith('ficha')?'ficha':p==='unete'?'unete':'inicio'}
function navMenu(p){const a=area(p);if((a==='vip'&&!isVip())||(a==='ficha'&&!identity))return [['inicio','Volver al inicio','home'],['unete','Únete a DEA','user'],['publico','Web pública','globe']];return a==='publico'?NAV_PUBLIC:a==='vip'?NAV_VIP:a==='ficha'?NAV_AGENT:[['unete','Unirse a DEA','user'],['publico/ingreso','Cómo ingresar','book']]}
function internalShell(p,body){const a=area(p);const nav=navMenu(p);const t=a==='vip'?'CENTRO DE CONTROL VIP':a==='publico'?'WEB PÚBLICA':a==='unete'?'ALTA DE AGENTES':'INTRANET · AGENTES';const sub=a==='vip'?'Dirección y operaciones internas':a==='publico'?'Información de la agencia':a==='unete'?'Ingreso desde R2 · Agente de Enlace':'Consulta personal y solo lectura';const crumb=p.split('/');const crumbs=[['Inicio','inicio']];if(crumb[0]==='publico')crumbs.push(['Web pública','publico']);if(crumb[0]==='vip')crumbs.push(['Acceso VIP','vip']);if(crumb[0]==='ficha')crumbs.push(['Mi expediente','ficha']);if(crumb[0]==='unete')crumbs.push(['Únete a DEA','unete']);if(crumb.length>1)crumbs.push([({agencia:'La agencia',jerarquia:'Jerarquía',departamentos:'Departamentos',founders:'Founders',ingreso:'Cómo ingresar',normativa:'Normativa',solicitudes:'Solicitudes',agentes:'Agentes',ascensos:'Ascensos',rangos:'Rangos y normas',nominas:'Nóminas y extras',historial:'Historial',configuracion:'Configuración',pagos:'Mis pagos'})[crumb[1]]||crumb[1],p]);const isV=a==='vip';return `<div class="mobile-overlay${mobileOpen?' active':''}" data-action="close-mobile"></div><div class="app-layout"><aside class="side${sidebarOpen?' expanded':''}${mobileOpen?' mobile-open':''}" aria-label="Menú principal"><div class="side-head"><a class="brand-home" href="#/inicio" aria-label="DEA HABBO ES, volver al inicio" title="Volver al inicio"><img src="./logo-dea-es.png" alt="Escudo oficial DEA"></a><div class="side-name">DEA HABBO ES<div class="side-brand-sub">DEPARTAMENTO ESPECIAL</div></div><button class="sidebar-toggle" title="Abrir o cerrar menú" aria-label="Abrir o cerrar menú" aria-expanded="${sidebarOpen}" data-action="toggle-sidebar">${I('menu')}</button></div><nav class="side-scroll"><div class="side-group">NAVEGACIÓN</div>${nav.map(([url,name,ic])=>`<a href="#/${url}" title="${esc(name)}" class="side-item${p===url?' active':''}${isV?' gold':''}">${I(ic)}<span>${esc(name)}</span></a>`).join('')}</nav><div class="side-bottom"><a href="#/inicio" title="Volver a portada" class="side-item">${I('back')}<span>Volver a portada</span></a>${identity?`<button type="button" class="side-item logout-link" data-action="logout">${I('logout')}<span>Cerrar sesión</span></button>`:''} </div></aside><div class="main"><header class="topbar"><div class="switch-head"><button class="btn ghost sm mobile-menu-btn" data-action="mobile-menu" aria-label="Mostrar menú">${I('menu')}</button><div><div class="topbar-title">${t}</div><div class="topbar-sub">${sub}</div></div></div><span class="topbar-badge${connected?'':' offline'}">${connected?'SISTEMA DISPONIBLE':'V6 · PREPARADO'}</span></header><main class="main-body"><div class="bread" aria-label="Ruta de navegación">${crumbs.map(([name,url],i)=>`${i?I('chevron'):''}${i===crumbs.length-1?`<b>${esc(name)}</b>`:`<button data-route="${url}">${esc(name)}</button>`}`).join('')}</div>${demoMode?`<div class="offline-bar">${I('alert')} <b>SIMULACIÓN:</b> registros, nóminas y modificaciones de ejemplo. No se guardan en la agencia ni se envían a Discord.</div>`:''}${body}<div class="watermark">DEA HABBO ES · YourDesignGPT · 10PEDRO</div></main><footer class="foot">DEA HABBO ES · <a href="https://yourdesigngpt.netlify.app/" target="_blank" rel="noopener noreferrer">Designed by 10PEDRO — YourDesignGPT</a></footer></div></div>`}
function head(k,title,desc){return `<div class="section-kicker">${k}</div><h1 class="page-title">${title}</h1><p class="page-desc">${desc}</p>`}
function tile(icon,label,val,gold=false){return `<div class="tile${gold?' gold':''}">${I(icon,true)}<div class="value">${val}</div><div class="hint">${label}</div></div>`}
function button(label,action,style='ghost'){return `<button class="btn ${style}" data-action="${action}">${label}</button>`}
function founders(){return `<div class="founders">${F.map(([name,title])=>`<div class="founder">${I('crown',true)}<span class="title">FOUNDER</span><strong>${esc(name)}</strong><small>${esc(title)}</small></div>`).join('')}</div><p class="dim">ORDER A–Z · Los cuatro Founders tienen idéntico nivel y representación.</p>`}
function groups(showEditor=false){return GROUPS.map(g=>{let r=ruleFor(g.id);return `<details class="rank-row" id="rank-${g.id}"><summary><div><strong>${g.id} · ${g.label}</strong><div><small>${esc(r.period)} · ${r.pay===null?'Nómina por definir':r.pay+' créditos'}${r.hours===null?'':' · '+r.hours+' h de presencia'}</small></div></div>${I('chevron')}</summary><div class="rank-inner"><div class="rank-pills">${g.ranks.length?g.ranks.map(x=>`<span>${esc(x)}</span>`).join(''):'<span>Rangos internos pendientes de definir</span>'}</div>${g.note?`<p class="dim">${esc(g.note)}</p>`:''}${showEditor?`<div class="btn-row spaced"><button class="btn gold sm" data-action="edit-rule" data-id="${g.id}">${I('edit')} Editar reglas (demo)</button></div>`:''}</div></details>`}).join('')}
function publicContent(p){if(p==='publico'){return head('DEA · HABBO HOTEL','Departamento Especial de Agentes','Una agencia organizada para aprender, progresar y colaborar dentro de Habbo Hotel.')+`<div class="columns"><div class="panel cyan"><div class="switch-head"><img class="logo-mini" src="./logo-dea-es.png" alt="DEA ES"><h3>Bienvenido a DEA HABBO ES</h3></div><p>Descubre nuestro sistema de formación, jerarquía y departamentos. El ingreso inicial comienza en la sala de Habbo y continúa en la web desde R2.</p><div class="btn-row"><a class="btn" href="#/publico/ingreso">Cómo ingresar ${I('arrow')}</a><a class="btn ghost" href="#/publico/jerarquia">Ver rangos</a></div></div><div class="panel gold"><h3>Identidad DEA</h3><p>Disciplina · Honor · Lealtad. Esta plataforma reúne información pública y, cuando se active, expedientes privados y gestión de dirección.</p><p class="dim">Proyecto de fans independiente, no vinculado oficialmente a Habbo Hotel.</p></div></div><div class="tiles three spaced">${tile('book','Formación en sala','45 min')}${tile('shield','Primer expediente oficial','R2')}${tile('crown','Founders','4',true)}</div>`}
if(p==='publico/agencia')return head('INSTITUCIONAL','Nuestra agencia','Información clara sobre la estructura de DEA HABBO ES.')+`<div class="columns equal"><div class="panel cyan"><h3>Qué es DEA</h3><p>DEA es una agencia de agentes organizada en Habbo Hotel. La web facilita el acceso a la información, la progresión y los procedimientos internos.</p><h3>Cómo funcionamos</h3><p>La formación inicial se realiza en la sala. Los expedientes web comienzan a partir de R2 · Agente de Enlace, una vez que dirección aprueba el alta.</p></div><div class="panel"><h3>Áreas principales</h3><div class="status-list">${['Control de Ascensos','Marketing','Eventos','Publicidad','Recursos Humanos','Desarrollo Web'].map(x=>`<div class="status-item">${I('check')}<strong>${x}</strong></div>`).join('')}</div></div></div>`;
if(p==='publico/jerarquia')return head('ESCALAFÓN OFICIAL','Jerarquía R1–R10','Consulta las categorías. Los rangos pendientes permanecen sin inventar.')+`<div class="slim">${groups()}</div>`;
if(p==='publico/departamentos')return head('ESTRUCTURA','Departamentos DEA','Seis áreas organizativas para coordinar el trabajo de la agencia.')+`<div class="tiles three">${['Control de Ascensos','Marketing','Eventos','Publicidad','Recursos Humanos','Desarrollo Web'].map((n,i)=>`<div class="panel"><div class="section-kicker">DEPARTAMENTO 0${i+1}</div><h3>${n}</h3><p class="dim">Responsabilidades y equipo definidos por dirección. Información detallada pendiente de publicación oficial.</p></div>`).join('')}</div>`;
if(p==='publico/founders')return head('DIRECCIÓN GENERAL','Equipo fundador','Los cuatro Founders aparecen en orden alfabético y en igualdad de representación.')+founders();
if(p==='publico/ingreso')return head('PROCESO DE INGRESO','Cómo unirse a DEA','Primero completas la formación en la sala y después solicitas el alta digital.')+`<div class="steps">${[['01','Cadete','Comienzas la formación en la sala Habbo'],['02','Aspirante a Operador','Primer tramo: 15 minutos'],['03','Operador en Práctica','Siguiente tramo: 15 minutos'],['04','Agente de Enlace','A los 45 minutos, alta oficial R2 previa comprobación']].map(s=>`<div class="step"><div class="number">${s[0]}</div><strong>${s[1]}</strong><small>${s[2]}</small></div>`).join('')}</div><div class="footer-cta"><h3>¿Has completado la formación?</h3><p class="dim">Solicita tu expediente con tu cuenta Discord y tu nickname de Habbo. Un Founder debe aprobarlo.</p><a href="#/unete" class="btn">Únete a DEA ${I('arrow')}</a></div>`;
if(p==='publico/normativa')return head('DOCUMENTACIÓN','Normativa básica','Normas informativas, sujetas a las decisiones y actualizaciones de los Founders.')+`<div class="slim stack">${[['Respeto y convivencia','Se espera respeto hacia compañeros, superiores y visitantes en todo momento.'],['Ascensos','Las promociones desde R2 requieren cumplir sus condiciones y autorización de personal habilitado.'],['Identificación','Cada expediente oficial se asociará a una cuenta de Discord y un nombre de Habbo verificado.'],['Nóminas y asistencia','Pagos ordinarios miércoles y domingo, con horas de presencia verificadas. Sábado: paga extra variable fijada por Founders.'],['Protección de datos','Los expedientes son privados. Los agentes solo podrán consultar su ficha personal.']].map(([n,t])=>`<details class="rank-row"><summary><strong>${n}</strong>${I('chevron')}</summary><div class="rank-inner">${t}</div></details>`).join('')}</div>`;
return publicContent('publico')}
function accessArea(which){const vip=which==='vip';const title=vip?'ACCESO VIP':'ÁREA DEL AGENTE';const desc=vip?'Solo los cuatro Founders autorizados pueden entrar al Centro de Control.':'Tu expediente es privado y se asocia a tu cuenta de Discord.';const denied=vip&&identity&&!identity.founder;return `<div class="auth-cover"><img src="./logo-dea-es.png" alt="DEA ES"><div class="section-kicker">${vip?'CENTRO DE CONTROL':'EXPEDIENTE PERSONAL'}</div><h1 class="page-title">${title}</h1><p class="page-desc">${desc}</p>${denied?`<div class="notice gold">${I('lock')} Tu Discord está identificado, pero tu cuenta no tiene permisos de Founder.</div><a class="btn ghost" href="#/ficha">Ir a mi expediente ${I('arrow')}</a>`:connected?`<a href="/auth/login" class="btn gold">${I('lock')} Entrar con Discord ${I('arrow')}</a>`:`<div class="offline-bar">${I('lock')} Acceso privado cerrado. Discord y el servidor aún deben configurarse. No se permiten entradas de demostración.</div><a href="#/publico" class="btn ghost">Visitar la web pública</a>`}</div>`}
function joinPage(){let hasIdentity=!!identity,member=identity?.agent;return head('ÚNETE A DEA','Tu ingreso oficial comienza en R2','Después de los tres tramos de formación en Habbo (45 minutos), usa Discord para solicitar el alta.')+`<div class="columns equal"><div class="panel cyan"><h3>Solicitud de ingreso</h3><p>Si ya eres Agente de Enlace, podrás solicitar la creación de tu expediente.</p><div class="status-list"><div class="status-item">${I('check')}<div><strong>45 minutos de formación</strong><p>Cadete → Aspirante a Operador → Operador en Práctica.</p></div></div><div class="status-item">${I('check')}<div><strong>Misión de Habbo confirmada</strong><p>Un responsable verifica tu acceso al rango oficial R2.</p></div></div><div class="status-item">${I('check')}<div><strong>Cuenta de Discord</strong><p>Se utiliza para identificarte y consultar posteriormente tu propia ficha.</p></div></div></div></div><div class="panel gold"><h3>${member?'Tu expediente ya está activo':hasIdentity?'Enviar solicitud':'Acceso mediante Discord'}</h3>${member?`<p>Ya tienes un expediente asignado. Accede a tu ficha para consultarlo.</p><a href="#/ficha" class="btn">Ver mi expediente</a>`:hasIdentity?`<p>Conectado: ${esc(identity.username)}. Introduce el nombre exacto de tu personaje.</p><form id="join-form"><div class="form-group"><label for="join-habbo">Nickname Habbo</label><input id="join-habbo" name="habbo" required maxlength="32" pattern="[a-zA-Z0-9_.:\\-]{2,32}" placeholder="Tu Habbo exacto"></div><div class="spaced"><button type="submit" class="btn">Enviar solicitud de aprobación</button></div></form><p class="dim">La ficha solo será activa tras la aprobación de un Founder.</p>`:`<p class="dim">No tienes que crear otra contraseña en la web. Primero identifica tu Discord.</p>${connected?'<a href="/auth/login" class="btn">Entrar con Discord</a>':'<div class="offline-bar">La conexión a Discord se activará cuando configuremos Cloudflare. No se aceptan solicitudes reales todavía.</div>'}`}</div></div>`}
function agentPage(p){if(!identity)return accessArea('agent');const agent=identity?.agent;if(!agent)return head('MI CUENTA','Solicitud en revisión','Una vez aprobada por un Founder, aquí aparecerá tu ficha oficial.')+`<div class="notice gold">Tu cuenta Discord todavía no tiene un expediente de agente asociado.</div>`;
let nick=demoMode?agent.habbo_name||agent.habbo:agent.habbo_name;let rank=ALL_RANKS[agent.rank_index??agent.rank]||ALL_RANKS[3];if(p==='ficha/historial')return head('EXPEDIENTE','Mis ascensos','Tu historial personal de movimientos de rango.')+`<div class="panel"><div class="table-scroll"><table><thead><tr><th>Fecha</th><th>Anterior</th><th>Nuevo</th></tr></thead><tbody>${demoMode?demo.promotions.filter(x=>x.habbo===nick).map(x=>`<tr><td>${esc(x.when)}</td><td>${esc(x.from)}</td><td>${esc(x.to)}</td></tr>`).join('')||'<tr><td colspan="3">Sin ascensos en esta demostración.</td></tr>':'<tr><td colspan="3">Disponible al vincular el historial real con Cloudflare.</td></tr>'}</tbody></table></div></div>`;
if(p==='ficha/pagos')return head('EXPEDIENTE','Mis pagos','Consulta tus propios pagos confirmados.')+`<div class="panel"><div class="notice gold">${demoMode?'Esta es una demostración, sin transferencias reales.':'Los pagos se consultarán en tu expediente una vez vinculado el módulo de nóminas.'}</div></div>`;
return head('INTRANET DE AGENTES','Mi expediente','Ficha personal de solo lectura; nadie puede modificar su rango desde aquí.')+`<div class="tiles">${tile('user','Nickname Habbo',esc(nick))}${tile('shield','Rango actual',esc(rank.name))}${tile('list','Categoría',esc(rank.cat))}${tile('clock','Próximo movimiento','Según normativa')}</div><div class="columns spaced"><div class="panel cyan"><h3>Estado del expediente</h3><p><span class="badge ok">Activo</span></p><p><strong>Discord:</strong> ${esc(demoMode?'Cuenta de ejemplo':identity.username)}</p><p><strong>Ingreso:</strong> ${esc(agent.joined_at||agent.date||'—')}</p><p><strong>Último ascenso:</strong> ${esc(agent.last_promoted_at||agent.last||'Sin registrar')}</p></div><div class="panel"><h3>Solo puedes consultar</h3><p>Tu historial de ascensos, los requisitos de tu próximo rango y el estado de las nóminas cuando se active el sistema real.</p><div class="btn-row"><a href="#/ficha/historial" class="btn ghost">Mis ascensos</a><a href="#/ficha/pagos" class="btn ghost">Mis pagos</a></div></div></div>`}
let realData={members:[],applications:[],promotions:[],audit:[],policies:[],payroll:[]};
async function fetchReal(){if(!connected||!identity?.founder||demoMode)return;try{const res=await Promise.allSettled([api('/api/members'),api('/api/applications'),api('/api/promotions'),api('/api/audit'),api('/api/policies'),api('/api/payments')]);let keys=['members','applications','promotions','audit','policies','payroll'];res.forEach((x,i)=>{if(x.status==='fulfilled'){let v=x.value;realData[keys[i]]=v[keys[i]]||v.events||v.payments||[]}});render()}catch(e){show(e.message)}}
const agents=()=>demoMode?demo.agents:realData.members;
const requests=()=>demoMode?demo.requests:realData.applications;
const promotions=()=>demoMode?demo.promotions:realData.promotions;
const payments=()=>demoMode?demo.payments:realData.payroll;
const audits=()=>demoMode?demo.audit:realData.audit;
function agentName(a){return a.habbo_name||a.habbo||''}
function agentRank(a){let index=Number(a.rank_index??a.rank);return ALL_RANKS[index]?.name||'No definido'}
function vipDashboard(){let arr=agents(),reqs=requests(),pending=reqs.filter(r=>(r.status||r.state)==='pendiente');let pays=payments().filter(x=>x.status==='pendiente');return head('DIRECCIÓN GENERAL','Centro de Control DEA','Toda la operativa de la agencia en un mismo panel: agentes, rangos, ascensos, nóminas y auditoría.')+`<div class="tiles">${tile('users','Agentes oficiales',arr.length)}${tile('user','Solicitudes pendientes',pending.length)}${tile('clock','Pagos pendientes',pays.length)}${tile('history','Movimientos registrados',audits().length,true)}</div><div class="columns spaced"><div class="panel gold"><h3>Acciones de dirección</h3><div class="tiles" style="grid-template-columns:repeat(2,minmax(0,1fr))">${[['Solicitudes','vip/solicitudes','user'],['Agentes','vip/agentes','users'],['Ascensos','vip/ascensos','arrow'],['Nóminas','vip/nominas','wallet']].map(([t,r,ic])=>`<a class="tile action-tile" href="#/${r}" aria-label="Abrir ${t}">${I(ic)}<strong>${t}</strong><div class="dim">${I('arrow')}</div></a>`).join('')}</div></div><div class="panel"><h3>Información esencial</h3><div class="status-list"><div class="status-item">${I('calendar')}<div><strong>Miércoles y domingo</strong><p>Nóminas ordinarias. Horas e importes según la categoría.</p></div></div><div class="status-item">${I('wallet')}<div><strong>Sábado</strong><p>Paga extra por asistencia. Los Founders fijan el importe cada semana.</p></div></div><div class="status-item">${I('shield')}<div><strong>Desde R2</strong><p>Expediente obligatorio; R1 se gestiona dentro de Habbo.</p></div></div></div></div></div><div class="footer-cta"><h3>Tabla oficial de rangos</h3><p class="dim">Consulta los tiempos de promoción y las nóminas. Los cambios autorizados quedarán registrados con su responsable en auditoría.</p><a class="btn gold" href="#/vip/rangos">Consultar jerarquía ${I('arrow')}</a></div>`}
function vipRequests(){let rs=requests();return head('CONTROL DE ALTAS','Solicitudes de ingreso','Solo llegan al expediente oficial quienes han completado R1 en Habbo y entran en R2.')+`<div class="notice gold">${I('alert')} Cada alta requiere comprobar el rango R2 y la identidad Habbo. El Founder debe verificar en Habbo el R2 y la identidad antes de aprobar.</div><div class="panel spaced"><div class="toolbar"><h3>Solicitudes</h3><span class="badge">${rs.length} registros${demoMode?' de ejemplo':''}</span></div><div class="table-scroll"><table><thead><tr><th>Habbo</th><th>Discord</th><th>Fecha</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>${rs.map(r=>{let state=r.status||r.state;return `<tr><td><strong>${esc(r.habbo_name||r.habbo)}</strong></td><td>${esc(r.discord_username||r.discord_id||r.discord||'—')}</td><td>${esc(r.created_at||r.date||'—')}</td><td><span class="badge ${state==='pendiente'?'wait':state==='aprobada'?'ok':'bad'}">${esc(state)}</span></td><td>${state==='pendiente'&&isVip()?`<button class="btn sm" data-action="approve" data-id="${esc(r.id)}">Aprobar R2</button> <button class="btn danger sm" data-action="reject" data-id="${esc(r.id)}">Rechazar</button>`:'—'}</td></tr>`}).join('')||'<tr><td colspan="5">No hay solicitudes.</td></tr>'}</tbody></table></div></div>`}
function vipAgents(){let arr=agents().filter(a=>(agentName(a)+' '+agentRank(a)).toLowerCase().includes(filter.toLowerCase()));return head('DIRECTORIO OFICIAL','Registro de agentes','Una sola ficha por usuario: rango, Discord asociado, ingreso y ascensos.')+`<div class="panel"><div class="toolbar"><label for="agent-search">Buscar agentes <input id="agent-search" placeholder="Habbo o rango..." value="${esc(filter)}" data-input="search" autocomplete="off"></label><div class="btn-row">${button(I('download')+' Exportar CSV','export-agents','ghost')}${demoMode?button(I('plus')+' Añadir ejemplo','add-agent','gold'):''}</div></div><div class="table-scroll"><table><thead><tr><th>Usuario Habbo</th><th>Discord</th><th>Rango actual</th><th>Alta</th><th>Acceso</th></tr></thead><tbody>${arr.map(a=>`<tr><td><strong>${esc(agentName(a))}</strong></td><td>${esc(a.discord||a.discord_id||'Sin vincular')}</td><td><span class="badge">${esc(agentRank(a))}</span></td><td>${esc(a.date||a.joined_at||'—')}</td><td><button class="btn sm ghost" data-route="vip/ascensos" data-select="${esc(a.id)}">Gestionar</button></td></tr>`).join('')||'<tr><td colspan="5">No se encuentran agentes.</td></tr>'}</tbody></table></div></div>`}
function vipPromotions(){let arr=agents();let chosen=arr.find(a=>String(a.id)===String(selectedAgent))||arr[0];let index=Number(chosen?.rank_index??chosen?.rank??3);let next=ALL_RANKS[index+1];let rule=ruleFor(ALL_RANKS[index]?.cat||'R2');return head('PROGRESIÓN','Control de ascensos','Selecciona un agente, comprueba su presencia en Habbo y registra el movimiento autorizado.')+`<div class="columns"><div class="panel gold"><h3>Registrar ascenso</h3>${arr.length?`<form id="promotion-form" class="form-grid"><div class="form-group full"><label for="prom-agent">Agente</label><select id="prom-agent" name="agent" data-input="select-agent">${arr.map(a=>`<option value="${esc(a.id)}" ${chosen&&String(a.id)===String(chosen.id)?'selected':''}>${esc(agentName(a))} · ${esc(agentRank(a))}</option>`).join('')}</select></div><div class="form-group"><label>Rango actual</label><input readonly value="${esc(agentRank(chosen))}"></div><div class="form-group"><label>Siguiente rango</label><input readonly value="${next?esc(next.name):'Por definir'}"></div><div class="form-group"><label>Intervalo mínimo</label><input readonly value="${esc(rule?.period||'Pendiente')}"></div><div class="form-group"><label>Último movimiento</label><input readonly value="${esc(chosen?.last||chosen?.last_promoted_at||'Sin datos')}"></div><div class="form-group full"><label>Observaciones</label><textarea name="note" placeholder="Datos de la comprobación presencial"></textarea></div><label class="checkrow form-group full"><input type="checkbox" name="presence" required> He comprobado presencialmente el ascenso en Habbo</label><div class="form-group full"><button class="btn gold" type="submit" ${!next?'disabled':''}>${I('check')} Confirmar ascenso${demoMode?' (demo)':''}</button></div></form>`:'<div class="empty">Sin agentes registrados.</div>'}<p class="dim">El servidor verificará el plazo y los permisos antes de guardar cada ascenso.</p></div><div class="panel"><h3>Historial reciente</h3>${promotions().length?promotions().slice(0,8).map(p=>`<div class="status-item">${I('arrow')}<div><strong>${esc(p.habbo||p.habbo_name||p.agent_id||'Agente')}</strong><p>${esc(p.to||ALL_RANKS[p.to_rank_index]?.name||'Ascenso')} · ${esc(p.when||p.promoted_at||'')}</p></div></div>`).join(''):'<div class="empty">No hay ascensos todavía.</div>'}</div></div>`}
function vipRules(){let rows=GROUPS.map(g=>{let r=ruleFor(g.id);return `<tr><td><strong>${g.id} · ${g.label}</strong></td><td>${esc(r.period)}</td><td>${r.hours===null?'Pendiente':r.hours+' h'}</td><td>${r.pay===null?'Pendiente':r.pay+' c'}</td><td>${isVip()?`<button class="btn sm ghost" data-action="edit-rule" data-id="${g.id}">${I('edit')} Editar</button>`:'—'}</td></tr>`}).join('');return head('NORMATIVA INTERNA','Tabla maestra de rangos','Tiempos, requisitos y salarios consultables. Modificaciones registradas con autor y fecha.')+`<div class="panel gold"><div class="toolbar"><h3>Parámetros oficiales</h3>${button(I('download')+' Exportar CSV','export-rules','ghost')}</div><div class="table-scroll"><table><thead><tr><th>Categoría</th><th>Ascenso</th><th>Presencia para nómina</th><th>Créditos</th><th>Editar</th></tr></thead><tbody>${rows}</tbody></table></div><div class="notice gold spaced">R1 se gestiona en la sala (15 + 15 + 15 minutos), sin alta web. R7–R10 contienen condiciones o rangos todavía pendientes de aprobar.</div></div><div class="panel spaced"><h3>Jerarquía por categorías</h3><div class="slim rank-detail">${groups()}</div></div>`}
function vipPayroll(){let pa=payments(),extras=demoMode?demo.extra:[];return head('CONTROL ECONÓMICO','Nóminas y pagas extra','Pagos ordinarios miércoles y domingo; los sábados, los Founders deciden una paga extra por asistencia.')+`<div class="tiles three">${tile('calendar','Miércoles','NÓMINA')}${tile('calendar','Sábado','EXTRA',true)}${tile('calendar','Domingo','NÓMINA')}</div><div class="columns spaced"><div class="panel cyan"><h3>Registrar nómina ordinaria</h3><form id="pay-form" class="form-grid"><div class="form-group"><label>Jornada</label><select name="day"><option value="miercoles">Miércoles</option><option value="domingo">Domingo</option></select></div><div class="form-group"><label>Fecha de jornada</label><input type="date" name="date" value="${date()}" required></div><div class="form-group full"><label>Agente</label><select name="agent" data-input="pay-agent">${agents().map(a=>`<option value="${esc(a.id)}">${esc(agentName(a))} · ${esc(agentRank(a))}</option>`).join('')}</select></div><div class="form-group"><label>Horas verificadas</label><input name="hours" type="number" min="0" max="500" step="0.5" placeholder="Horas" required></div><div class="form-group"><label>Créditos a entregar</label><input name="credits" type="number" min="0" max="100000" step="1" value="${ruleFor(ALL_RANKS[Number(agents()[0]?.rank_index??agents()[0]?.rank??3)]?.cat||'R2')?.pay??''}" placeholder="Según rango" readonly required></div><div class="form-group full"><label>Observaciones</label><input name="note" maxlength="200" placeholder="Opcional"></div><label class="checkrow form-group full"><input type="checkbox" required name="verified"> Asistencia verificada en Habbo</label><div class="form-group full"><button class="btn" type="submit">Registrar pago ordinario${demoMode?' (demo)':''}</button></div></form></div><div class="panel gold"><h3>Paga extra del sábado</h3><p class="dim">Cada sábado se establece el importe, sin cantidad fija predefinida. La dirección confirma las asistencias y los pagos.</p><form id="extra-form" class="form-grid"><div class="form-group"><label>Fecha de sábado</label><input name="date" type="date" value="${date()}" required></div><div class="form-group"><label>Extra por agente (c)</label><input name="amount" type="number" min="0" max="100000" step="1" required placeholder="Importe acordado"></div><div class="form-group full"><label>Agentes asistentes</label><div class="status-list">${agents().map(a=>`<label class="checkrow"><input type="checkbox" name="attend" value="${esc(a.id)}"> ${esc(agentName(a))} · ${esc(agentRank(a))}</label>`).join('')||'<p>No hay agentes registrados.</p>'}</div></div><div class="form-group full"><label>Observación</label><input name="note" maxlength="200" placeholder="Acuerdo de Founders / comprobación"></div><div class="form-group full"><button type="submit" class="btn gold">${I('check')} Registrar paga extra${demoMode?' (demo)':''}</button></div></form></div></div><div class="panel spaced"><div class="toolbar"><h3>Pagos registrados</h3>${button(I('download')+' Exportar CSV','export-payments')}</div><div class="table-scroll"><table><thead><tr><th>Jornada</th><th>Agente</th><th>Créditos</th><th>Fecha</th><th>Estado</th></tr></thead><tbody>${pa.map(x=>`<tr><td>${esc(x.type||x.kind||'Nómina')}</td><td>${esc(x.habbo||x.habbo_name||x.agent_id||'')}</td><td><strong>${esc(x.amount??x.credits)} c</strong></td><td>${esc(x.date||x.paid_at||'')}</td><td><span class="badge ok">${esc(x.status||'Pagado')}</span></td></tr>`).join('')||'<tr><td colspan="5">No hay pagos registrados.</td></tr>'}</tbody></table></div></div>`}
function vipHistory(){return head('TRAZABILIDAD','Historial y auditoría','Las acciones, pagos, ascensos y cambios de reglas quedan asociados a su responsable.')+`<div class="toolbar">${button(I('download')+' Exportar auditoría CSV','export-audit')}<span class="badge">${audits().length} movimientos</span></div><div class="panel"><div class="table-scroll"><table><thead><tr><th>Fecha</th><th>Responsable</th><th>Acción</th><th>Detalle</th></tr></thead><tbody>${audits().map(x=>`<tr><td>${esc(x.when||x.created_at||'')}</td><td>${esc(x.by||x.actor_discord_id||'')}</td><td><strong>${esc(x.action||'')}</strong></td><td>${esc(x.detail||x.detail_json||'')}</td></tr>`).join('')||'<tr><td colspan="4">Sin modificaciones todavía.</td></tr>'}</tbody></table></div></div><div class="notice gold spaced">Las rectificaciones deben registrarse como nuevos eventos, no borrando operaciones anteriores. En producción, este control debe estar protegido desde el servidor.</div>`}
function vipConfig(){return head('CONFIGURACIÓN','Administración y permisos','La seguridad del Centro VIP dependerá de los IDs verificados de Discord, nunca del nombre escrito en la web.')+`<div class="stack"><div class="panel gold"><h3>Founders</h3>${founders()}</div><div class="columns equal"><div class="panel"><h3>Conexiones</h3><div class="status-list"><div class="status-item">${I('database')}<div><strong>Cloudflare D1</strong><p>${connected?'API disponible':'Pendiente de activar y configurar'}</p></div></div><div class="status-item">${I('lock')}<div><strong>Discord OAuth</strong><p>${connected?'Configuración disponible':'Pendiente de conectar'}</p></div></div><div class="status-item">${I('history')}<div><strong>Tablón Discord / Excel</strong><p>Integraciones externas pendientes. Las exportaciones CSV ya son demostrables.</p></div></div></div></div><div class="panel"><h3>Permisos</h3><p>Al inicio, las operaciones desde R2 se autorizan únicamente por los cuatro Founders. En el futuro se podrán delegar ascensos limitados a personal autorizado.</p><p>Los rangos de formación R1 se gestionan en la sala, sin crear expediente ni usuario de web.</p><div class="notice gold">Las autorizaciones reales deben comprobarse en Cloudflare Workers. El modo demo no concede privilegios.</div></div></div></div>`}
function vipPage(p){if(!isVip())return accessArea('vip');if(p==='vip/solicitudes')return vipRequests();if(p==='vip/agentes')return vipAgents();if(p==='vip/ascensos')return vipPromotions();if(p==='vip/rangos')return vipRules();if(p==='vip/nominas')return vipPayroll();if(p==='vip/historial')return vipHistory();if(p==='vip/configuracion')return vipConfig();return vipDashboard()}
function render(){const p=pathname();const a=area(p);if(a==='inicio'){ROOT.innerHTML=layoutHome();return}let body=a==='publico'?publicContent(p):a==='unete'?joinPage():a==='vip'?vipPage(p):agentPage(p);ROOT.innerHTML=internalShell(p,body);document.title=`${({publico:'Web pública',vip:'Acceso VIP',unete:'Únete a DEA',ficha:'Mi expediente'})[a]||'Inicio'} | DEA HABBO ES`}
function getAgent(id){return demo.agents.find(a=>String(a.id)===String(id))}
function asCSV(filename,headings,rows){const q=v=>'"'+String(v??'').replaceAll('"','""')+'"';let txt='\uFEFF'+[headings,...rows].map(r=>r.map(q).join(';')).join('\r\n');let url=URL.createObjectURL(new Blob([txt],{type:'text/csv;charset=utf-8'}));let a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);show('CSV descargado. Protege los datos incluidos.');}
async function onAction(el){const act=el.dataset.action;const id=el.dataset.id;if(act==='toggle-sidebar'){if(innerWidth<711){mobileOpen=!mobileOpen}else sidebarOpen=!sidebarOpen;render();return}if(act==='mobile-menu'){mobileOpen=!mobileOpen;render();return}if(act==='close-mobile'){mobileOpen=false;render();return}if(act==='logout'){try{await api('/api/logout','POST',{});identity=null;realData={members:[],applications:[],promotions:[],audit:[],policies:[],payroll:[]};route('inicio');render();show('Sesión cerrada correctamente')}catch(e){show(e.message)}return}if(act==='add-agent'){let nick=prompt('Nombre ficticio de agente (solo demostración):');if(!nick)return;nick=nick.trim();if(!/^[a-zA-Z0-9_.:\-]{2,32}$/.test(nick)){show('Introduce un nickname válido de Habbo');return}if(demo.agents.some(x=>agentName(x).toLowerCase()===nick.toLowerCase())){show('Ese agente ya existe en la demo');return}demo.agents.push({id:demo.seq++,habbo:nick,discord:'Sin vincular (demo)',rank:3,date:date(),last:date()});log('Alta demo',nick);render();return}if(act==='approve'||act==='reject'){if(!demoMode){if(!identity?.founder)return show('Solo Founders');if(act==='approve'&&!confirm('¿Has comprobado el R2 y la identidad de Habbo?'))return;try{await api('/api/applications/'+encodeURIComponent(id)+'/'+(act==='approve'?'approve':'reject'),'POST',{habbo_verified:act==='approve',reason:act==='reject'?'No verificado':''});show('Solicitud revisada');await fetchReal()}catch(e){show(e.message)}return}let r=demo.requests.find(x=>String(x.id)===String(id));if(!r){show('Solicitud no encontrada');return}if(!demoMode){show('Operación real pendiente de conectar');return}if(act==='approve'){if(demo.agents.some(x=>agentName(x).toLowerCase()===r.habbo.toLowerCase())){show('El expediente ya existe');return}r.state='aprobada';demo.agents.push({id:demo.seq++,habbo:r.habbo,discord:r.discord,rank:3,date:date(),last:date()})}else r.state='rechazada';log(act==='approve'?'Aprobación R2':'Rechazo de solicitud',r.habbo);render();return}if(act==='edit-rule'){const g=GROUPS.find(x=>x.id===id),r=ruleFor(id);if(!g)return;const period=prompt(`Tiempo de ascenso para ${id}. Valor anterior: ${r.period}`,r.period);if(period===null)return;if(!period.trim()||period.length>80){show('Introduce un plazo válido');return}const h=prompt(`Horas de nómina para ${id}. Vacío = pendiente`,r.hours??'');if(h===null)return;const pay=prompt(`Créditos de nómina para ${id}. Vacío = pendiente`,r.pay??'');if(pay===null)return;const hourN=h.trim()?Number(h):null,payN=pay.trim()?Number(pay):null;if((hourN!==null&&(!Number.isFinite(hourN)||hourN<0||hourN>999))||(payN!==null&&(!Number.isInteger(payN)||payN<0||payN>100000))){show('Horas o créditos no válidos');return}if(!confirm(demoMode?'¿Guardar modificación DE EJEMPLO?':'¿Guardar modificación de la normativa OFICIAL con auditoría?'))return;if(!demoMode){try{await api('/api/policies/'+encodeURIComponent(id),'POST',{period_label:period.trim(),payroll_hours:hourN,payroll_credits:payN});show('Norma oficial actualizada');await fetchReal()}catch(e){show(e.message)}return}const prev=JSON.stringify(r);demo.rules[id]={period:period.trim(),hours:hourN,pay:payN};log('Normativa modificada '+id,prev+' → '+JSON.stringify(demo.rules[id]));render();show('Cambio ficticio registrado en el historial');return}if(act.startsWith('export-')){let d=act.slice(7);if(d==='agents')asCSV('DEA-agentes.csv',['Habbo','Discord','Rango','Alta'],agents().map(a=>[agentName(a),a.discord||a.discord_id,agentRank(a),a.date||a.joined_at]));else if(d==='rules')asCSV('DEA-rangos.csv',['Categoría','Tiempo de ascenso','Horas nómina','Créditos'],GROUPS.map(g=>[g.id+' · '+g.label,ruleFor(g.id).period,ruleFor(g.id).hours,ruleFor(g.id).pay]));else if(d==='payments')asCSV('DEA-nominas.csv',['Tipo','Agente','Créditos','Fecha','Estado'],payments().map(x=>[x.type,x.habbo,x.amount,x.date,x.status]));else if(d==='audit')asCSV('DEA-historial.csv',['Fecha','Responsable','Acción','Detalle'],audits().map(x=>[x.when||x.created_at,x.by||x.actor_discord_id,x.action,x.detail||x.detail_json]));return}}
async function onForm(form){const data=new FormData(form);const fid=form.id;if(fid==='join-form'){let name=String(data.get('habbo')||'').trim();if(!/^[a-zA-Z0-9_.:\-]{2,32}$/.test(name)){show('Nickname Habbo no válido');return}if(!connected){show('Para registrar solicitudes reales es necesario activar Cloudflare y Discord');return}try{await api('/api/applications','POST',{habbo_name:name});show('Solicitud enviada para aprobación de Founders');route('ficha')}catch(e){show(e.message)}return}if(!demoMode){try{
 if(fid==='promotion-form'){
  if(!data.get('presence'))return show('Comprueba la presencia en Habbo');
  const member=agents().find(a=>String(a.id)===String(data.get('agent')));if(!member)return show('Agente no encontrado');
  await api('/api/members/'+encodeURIComponent(member.id)+'/promotions','POST',{to_rank_index:Number(member.rank_index)+1,presence_verified:true,note:String(data.get('note')||'')});show('Ascenso oficial guardado');await fetchReal();return;
 }
 if(fid==='pay-form'){
  const result=await api('/api/payments','POST',{agent_id:String(data.get('agent')),kind:String(data.get('day')),payment_date:String(data.get('date')),hours_verified:Number(data.get('hours')),note:String(data.get('note')||'')});show('Nómina guardada: '+result.credits+' créditos');await fetchReal();return;
 }
 if(fid==='extra-form'){
  await api('/api/extra-sessions','POST',{payment_date:String(data.get('date')),credits_per_agent:Number(data.get('amount')),agent_ids:data.getAll('attend'),note:String(data.get('note')||'')});show('Paga extra del sábado registrada');await fetchReal();return;
 }
 }catch(e){show(e.message);return}return}
 if(fid==='promotion-form'){let member=getAgent(data.get('agent'));if(!member)return;let next=ALL_RANKS[member.rank+1];if(!next)return show('El siguiente rango todavía no está definido');if(!data.get('presence'))return show('Debes verificar la presencia en Habbo');if(!confirm(`¿Registrar ASCENSO DE EJEMPLO para ${member.habbo} a ${next.name}?`))return;const from=agentRank(member);member.rank++;member.last=date();demo.promotions.unshift({habbo:member.habbo,from,to:next.name,when:time(),by:'FOUNDER DEMO'});log('Ascenso demo',member.habbo+': '+from+' → '+next.name);render();show('Ascenso ficticio registrado');return}if(fid==='pay-form'){let member=getAgent(data.get('agent'));if(!member)return;const kind=String(data.get('day')),d=String(data.get('date')),hours=Number(data.get('hours')),credits=Number(data.get('credits'));if(!Number.isFinite(hours)||hours<0||!Number.isInteger(credits)||credits<0)return show('Horas y créditos deben ser válidos');const weekday=new Date(d+'T12:00:00Z').getUTCDay();if((kind==='miercoles'&&weekday!==3)||(kind==='domingo'&&weekday!==0))return show('La fecha seleccionada no corresponde al día de nómina indicado');let cat=ALL_RANKS[member.rank]?.cat||'R2',rule=demo.rules[cat];if(rule.hours!==null&&hours<rule.hours)return show(`No alcanza las ${rule.hours} horas requeridas en ${cat}`);if(rule.pay!==null&&credits!==rule.pay)return show(`La nómina de ${cat} son ${rule.pay} créditos: consulta o modifica normativa`);if(demo.payments.some(p=>p.type===kind&&p.date===d&&p.habbo===member.habbo))return show('Ya existe un pago para ese agente y esa jornada');if(!confirm('Confirmar pago ficticio. Esto NO transfiere créditos de Habbo.'))return;demo.payments.unshift({type:kind,habbo:member.habbo,amount:credits,date:d,status:'Pagado'});log('Nómina demo',member.habbo+' · '+credits+' c · '+d);render();show('Pago simulado registrado');return}if(fid==='extra-form'){let d=String(data.get('date')),amount=Number(data.get('amount')),ids=data.getAll('attend');if(new Date(d+'T12:00:00Z').getUTCDay()!==6)return show('La paga extra debe registrarse con fecha de sábado');if(!Number.isInteger(amount)||amount<0||amount>100000)return show('Indica una cantidad entera válida');if(!ids.length)return show('Marca como mínimo un agente presente');if(ids.some(id=>!getAgent(id)))return show('Agente no encontrado');if(ids.some(id=>demo.payments.some(p=>p.type==='extra'&&p.date===d&&p.habbo===getAgent(id).habbo)))return show('Alguno de los asistentes ya tiene extra registrada ese sábado');if(!confirm(`¿Simular paga extra de ${amount} c a ${ids.length} asistentes (total ${amount*ids.length} c)?`))return;ids.forEach(id=>{let a=getAgent(id);demo.payments.unshift({type:'extra',habbo:a.habbo,amount,date:d,status:'Pagado'})});demo.extra.unshift({date:d,amount,attendees:ids.length});log('Paga extra demo',`${d}: ${amount} créditos × ${ids.length} agentes`);render();show('Paga extra ficticia registrada');return}}
ROOT.addEventListener('click',e=>{let element=e.target.closest('[data-action],[data-route]');if(!element)return;if(element.dataset.route){e.preventDefault();if(element.dataset.select)selectedAgent=element.dataset.select;mobileOpen=false;route(element.dataset.route);if(pathname()===element.dataset.route)render();return}e.preventDefault();onAction(element)});
ROOT.addEventListener('submit',e=>{e.preventDefault();onForm(e.target).catch(err=>show(err.message))});
ROOT.addEventListener('input',e=>{if(e.target.dataset.input==='search'){filter=e.target.value;const pos=e.target.selectionStart;const input=e.target;const tbody=document.querySelector('tbody');if(tbody){let filtered=agents().filter(a=>(agentName(a)+' '+agentRank(a)).toLowerCase().includes(filter.toLowerCase()));tbody.innerHTML=filtered.map(a=>`<tr><td><strong>${esc(agentName(a))}</strong></td><td>${esc(a.discord||a.discord_id||'Sin vincular')}</td><td><span class="badge">${esc(agentRank(a))}</span></td><td>${esc(a.date||a.joined_at||'—')}</td><td><button class="btn sm ghost" data-route="vip/ascensos" data-select="${esc(a.id)}">Gestionar</button></td></tr>`).join('')||'<tr><td colspan="5">No se encuentran agentes.</td></tr>'}}if(e.target.dataset.input==='pay-agent'){let ag=agents().find(a=>String(a.id)===String(e.target.value));if(ag){let cat=ALL_RANKS[Number(ag.rank_index??ag.rank)]?.cat;let pay=ruleFor(cat||'R2')?.pay;let inp=document.querySelector('input[name=credits]');if(inp)inp.value=pay??''}}if(e.target.dataset.input==='select-agent'){selectedAgent=e.target.value;render()}});
window.addEventListener('hashchange',()=>{mobileOpen=false;window.scrollTo(0,0);render()});
render();checkSession();
